targets.query:
from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "haven.outdoor" and r._field == "aqi")

from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "haven.outdoor" and (r._field == "o3" or r._field == "no2" or r._field == "co"))

from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "haven.outdoor" and (r._field == "pm25" or r._field == "pm10"))

from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "haven.outdoor" and (r._field == "grass" or r._field == "ragweed" or r._field == "oak" or r._field == "birch" or r._field == "alder" or r._field == "hazel" or r._field == "mugwort"))
